/**
 * ZUGFeRD PDF/A-3 Embedding
 *
 * Embeds a factur-x.xml (ZUGFeRD/Factur-X XML) into an existing PDF buffer,
 * producing a hybrid document that readers can process both visually and
 * programmatically.
 *
 * What this does:
 *  1. Loads the PDF generated by @react-pdf/renderer
 *  2. Attaches factur-x.xml as an embedded file with AFRelationship=Alternative
 *  3. Injects ZUGFeRD-compliant XMP metadata into the PDF catalog
 *  4. Marks the document as PDF/A-3b in the metadata
 *  5. Returns the enhanced PDF buffer
 *
 * Note on PDF/A-3 compliance:
 *  Full PDF/A-3 validation (via VeraPDF) requires embedded fonts, output intents,
 *  and color spaces. The PDF produced by @react-pdf/renderer is not fully PDF/A-3
 *  compliant out-of-the-box. For strict compliance, a dedicated PDF/A converter
 *  (e.g. Ghostscript, pdftron) would be needed in CI/CD.
 *  However, the XML embedding and XMP metadata implemented here are correct per
 *  the ZUGFeRD/Factur-X specification and are recognized by all major e-invoice
 *  validators (Mustang-Project, KOSIT).
 */

import { PDFDocument, PDFName, AFRelationship } from "pdf-lib";

// ─── XMP Metadata Builder ────────────────────────────────────────────────────

/**
 * Builds the XMP metadata XML string for a ZUGFeRD/Factur-X PDF.
 *
 * The XMP must declare:
 *  - pdfaid:part=3, pdfaid:conformance=B  →  PDF/A-3b identification
 *  - fx:* properties                       →  Factur-X extension schema
 *  - pdfaExtension schema declaration      →  Required for PDF/A compliance
 */
function buildZugferdXmpMetadata(
  conformanceLevel: string,
  documentFileName: string,
  creationDate: Date,
  modificationDate: Date,
  producerName: string
): string {
  const isoDate = (d: Date) => d.toISOString();

  return `<?xpacket begin="\uFEFF" id="W5M0MpCehiHzreSzNTczkc9d"?>
<x:xmpmeta xmlns:x="adobe:ns:meta/">
  <rdf:RDF xmlns:rdf="http://www.w3.org/1999/02/22-rdf-syntax-ns#">

    <!-- PDF basic metadata -->
    <rdf:Description rdf:about=""
        xmlns:dc="http://purl.org/dc/elements/1.1/"
        xmlns:xmp="http://ns.adobe.com/xap/1.0/"
        xmlns:pdf="http://ns.adobe.com/pdf/1.3/">
      <xmp:CreateDate>${isoDate(creationDate)}</xmp:CreateDate>
      <xmp:ModifyDate>${isoDate(modificationDate)}</xmp:ModifyDate>
      <xmp:CreatorTool>${producerName}</xmp:CreatorTool>
      <pdf:Producer>${producerName}</pdf:Producer>
    </rdf:Description>

    <!-- PDF/A-3b identification (required for ZUGFeRD embedding) -->
    <rdf:Description rdf:about=""
        xmlns:pdfaid="http://www.aiim.org/pdfa/ns/id/">
      <pdfaid:part>3</pdfaid:part>
      <pdfaid:conformance>B</pdfaid:conformance>
    </rdf:Description>

    <!-- Factur-X / ZUGFeRD extension properties -->
    <rdf:Description rdf:about=""
        xmlns:fx="urn:factur-x:pdfa:CrossIndustryDocument:invoice:1p0#">
      <fx:DocumentFileName>${documentFileName}</fx:DocumentFileName>
      <fx:DocumentType>INVOICE</fx:DocumentType>
      <fx:Version>1.0</fx:Version>
      <fx:ConformanceLevel>${conformanceLevel}</fx:ConformanceLevel>
    </rdf:Description>

    <!-- PDF/A extension schema declaration (required by PDF/A spec) -->
    <rdf:Description rdf:about=""
        xmlns:pdfaExtension="http://www.aiim.org/pdfa/ns/extension/"
        xmlns:pdfaSchema="http://www.aiim.org/pdfa/ns/schema#"
        xmlns:pdfaProperty="http://www.aiim.org/pdfa/ns/property#">
      <pdfaExtension:schemas>
        <rdf:Bag>
          <rdf:li rdf:parseType="Resource">
            <pdfaSchema:schema>Factur-X PDFA Extension Schema</pdfaSchema:schema>
            <pdfaSchema:namespaceURI>urn:factur-x:pdfa:CrossIndustryDocument:invoice:1p0#</pdfaSchema:namespaceURI>
            <pdfaSchema:prefix>fx</pdfaSchema:prefix>
            <pdfaSchema:property>
              <rdf:Seq>
                <rdf:li rdf:parseType="Resource">
                  <pdfaProperty:name>DocumentFileName</pdfaProperty:name>
                  <pdfaProperty:valueType>Text</pdfaProperty:valueType>
                  <pdfaProperty:category>external</pdfaProperty:category>
                  <pdfaProperty:description>name of the embedded XML invoice file</pdfaProperty:description>
                </rdf:li>
                <rdf:li rdf:parseType="Resource">
                  <pdfaProperty:name>DocumentType</pdfaProperty:name>
                  <pdfaProperty:valueType>Text</pdfaProperty:valueType>
                  <pdfaProperty:category>external</pdfaProperty:category>
                  <pdfaProperty:description>INVOICE</pdfaProperty:description>
                </rdf:li>
                <rdf:li rdf:parseType="Resource">
                  <pdfaProperty:name>Version</pdfaProperty:name>
                  <pdfaProperty:valueType>Text</pdfaProperty:valueType>
                  <pdfaProperty:category>external</pdfaProperty:category>
                  <pdfaProperty:description>The actual version of the Factur-X standard</pdfaProperty:description>
                </rdf:li>
                <rdf:li rdf:parseType="Resource">
                  <pdfaProperty:name>ConformanceLevel</pdfaProperty:name>
                  <pdfaProperty:valueType>Text</pdfaProperty:valueType>
                  <pdfaProperty:category>external</pdfaProperty:category>
                  <pdfaProperty:description>The conformance level of the embedded XML invoice</pdfaProperty:description>
                </rdf:li>
              </rdf:Seq>
            </pdfaSchema:property>
          </rdf:li>
        </rdf:Bag>
      </pdfaExtension:schemas>
    </rdf:Description>

  </rdf:RDF>
</x:xmpmeta>
<?xpacket end="w"?>`;
}

// ─── Main Embed Function ──────────────────────────────────────────────────────

export interface EmbedOptions {
  /** Conformance level string shown in XMP — e.g. "EN 16931" */
  conformanceLevel?: string;
  /** Filename for the embedded XML — must be "factur-x.xml" per spec */
  xmlFileName?: string;
  /** Producer string shown in PDF metadata */
  producer?: string;
}

/**
 * Embeds a ZUGFeRD/Factur-X XML file into an existing PDF buffer.
 *
 * @param pdfBuffer  - The PDF generated by @react-pdf/renderer
 * @param xmlString  - The factur-x.xml content (UTF-8)
 * @param options    - Optional overrides
 * @returns Enhanced PDF buffer with embedded XML and XMP metadata
 */
export async function embedZugferdXml(
  pdfBuffer: Buffer,
  xmlString: string,
  options: EmbedOptions = {}
): Promise<Buffer> {
  const {
    conformanceLevel = "EN 16931",
    xmlFileName = "factur-x.xml",
    producer = "Zoonox",
  } = options;

  const now = new Date();
  const xmlBytes = Buffer.from(xmlString, "utf-8");

  // Load the existing PDF
  const pdfDoc = await PDFDocument.load(pdfBuffer, {
    // Allow loading PDFs that may have minor issues
    ignoreEncryption: true,
    updateMetadata: false,
  });

  // ── Embed the XML as an attached file ────────────────────────────────────────
  // AFRelationship.Alternative = the XML is an alternative representation of the
  // PDF content (required by ZUGFeRD/Factur-X specification)
  await pdfDoc.attach(xmlBytes, xmlFileName, {
    mimeType: "application/xml",
    description: `Factur-X/ZUGFeRD 2.x ${conformanceLevel} Invoice`,
    creationDate: now,
    modificationDate: now,
    afRelationship: AFRelationship.Alternative,
  });

  // ── Inject ZUGFeRD XMP metadata into PDF catalog ─────────────────────────────
  // pdf-lib does not expose a high-level XMP API, so we work with the PDF context
  // directly by creating a new Metadata stream in the PDF catalog.
  const xmpString = buildZugferdXmpMetadata(
    conformanceLevel,
    xmlFileName,
    now,
    now,
    producer
  );
  const xmpBytes = new TextEncoder().encode(xmpString);

  // Create the XMP metadata stream
  const metadataStream = pdfDoc.context.stream(xmpBytes, {
    Type: "Metadata",
    Subtype: "XML",
    Length: xmpBytes.length,
  });

  // Register the stream and point the catalog's Metadata key at it
  const metadataRef = pdfDoc.context.register(metadataStream);
  pdfDoc.catalog.set(PDFName.of("Metadata"), metadataRef);

  // ── Save and return ─────────────────────────────────────────────────────────
  const resultBytes = await pdfDoc.save({
    // Use object streams for smaller file size
    useObjectStreams: true,
    // Add update cross-reference table for efficient incremental writes
    addDefaultPage: false,
  });

  return Buffer.from(resultBytes);
}
